public class AdministratorFeaturesTest {
 static int checks=0;static void check(boolean ok,String text){checks++;if(!ok)throw new AssertionError(text);}
 static class Model extends InternalContest {List<Run> runs=new ArrayList<>();public Run[] getRuns(){return runs.toArray(new Run[0]);}}
 static class Fixture extends DashboardBridge {
  Model data=new Model();List<String> calls=new ArrayList<>();PlaybackInfo lastPlayback;IInternalController adapter;Contest api;
  Fixture(Path dir)throws Exception{
   privateBase=dir;Files.createDirectories(dir);data.setSiteNumber(1);data.setClientId(new ClientId(1,ClientType.Type.ADMINISTRATOR,2));data.addContestTime(new ContestTime(1));ContestInformation info=new ContestInformation();info.setMaxOutputSizeInBytes(1048576);data.addContestInformation(info);Site site=new Site("Fixture site",1);data.addSite(site);Language lang=new Language("GNU C++17");lang.setCompileCommandLine("/opt/lcpc/bin/compile17 {:mainfile} {:basename}");lang.setProgramExecuteCommandLine("./{:basename}");lang.setExecutableIdentifierMask("{:basename}");data.addLanguage(lang);
   for(ClientType.Type type:new ClientType.Type[]{ClientType.Type.ADMINISTRATOR,ClientType.Type.JUDGE,ClientType.Type.TEAM}){Account a=new Account(new ClientId(1,type,type==ClientType.Type.ADMINISTRATOR?2:1),"Fixture-secret-password",1);a.setDisplayName(type.toString());a.clearListAndLoadPermissions(new PermissionGroup().getPermissionList(type));data.addAccount(a);}
   Problem p=new Problem("Fixture problem");p.setLetter("A");p.setShortName("alpha");p.setSandboxType(Problem.SandboxType.PC2_INTERNAL_SANDBOX);p.setSandboxProgramName("pc2sandbox.sh");p.setSandboxCmdLine("./{:sandboxprogramname} {:memlimit} {:timelimit}");p.setMemoryLimitMB(128);p.setTimeOutInSeconds(2);p.setPrelimaryNotification(false);p.addTestCaseFilenames("01.in","01.ans");ProblemDataFiles f=new ProblemDataFiles(p);f.setJudgesDataFiles(new SerializedFile[]{new SerializedFile("01.in","1 2".getBytes())});f.setJudgesAnswerFiles(new SerializedFile[]{new SerializedFile("01.ans","3".getBytes())});data.addProblem(p,f);data.addJudgement(new Judgement("Accepted",Judgement.ACRONYM_ACCEPTED));data.addJudgement(new Judgement("Wrong Answer",Judgement.ACRONYM_WRONG_ANSWER));
   adapter=(IInternalController)Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{IInternalController.class},(proxy,method,args)->{
    calls.add(method.getName());String target=switch(method.getName()){
     case "addNewAccount"->"addAccount";case "addNewAccounts"->"addAccounts";case "addNewLanguage"->"addLanguage";case "addNewGroup"->"addGroup";case "addNewJudgement"->"addJudgement";case "addNewCategory"->"addCategory";case "addNewSite"->"addSite";case "addNewBalloonSettings"->"addBalloonSettings";case "addNewClientSettings"->"addClientSettings";case "updateFinalizeData"->"setFinalizeData";default->method.getName();};
    if(target.equals("getLog"))return StaticLog.getLog();
    if(target.equals("startPlayback")){lastPlayback=(PlaybackInfo)args[0];data.updatePlaybackInfo(lastPlayback);return null;}
    if(target.equals("updateRun")){Run r=(Run)args[0];data.runs.removeIf(x->x.getElementId().equals(r.getElementId()));data.runs.add(r);return null;}
    if(target.equals("sendToLocalServer")||target.equals("cancelRun")||target.equals("forceConnectionDrop")||target.equals("logoffUser")||target.equals("resetContest")||target.equals("submitRun"))return null;
    if(target.equals("getContest"))return data;if(target.equals("getPluginList"))return new edu.csus.ecs.pc2.ui.UIPlugin[0];
    try{return Model.class.getMethod(target,method.getParameterTypes()).invoke(data,args);}catch(NoSuchMethodException missing){throw new UnsupportedOperationException(method.getName());}
   });
   api=new Contest(data,adapter,StaticLog.getLog());api.setLoggedIn(true);internalContest=data;controller=adapter;contest=api;
  }
  public Contest getContest(){return api;}IInternalContest model(){return data;}IInternalController control(){return adapter;}
  public void addAccount(String type,String name,String password){throw new UnsupportedOperationException();}
 }
 static JSONObject command(String c)throws Exception{return new JSONObject().put("command",c);}
 static void rejects(Fixture s,JSONObject a,String reason)throws Exception{int n=s.calls.size();try{AdministratorFeatures.operations(s,a);throw new AssertionError("Should reject: "+reason);}catch(IllegalArgumentException|SecurityException expected){checks++;}check(s.calls.size()==n,"Rejected action cannot invoke controller: "+reason);}
 public static void main(String[]args){try{run();System.out.println("Native administrator checks passed: "+checks);System.exit(0);}catch(Throwable error){error.printStackTrace();System.exit(1);}}
 static void run()throws Exception{
  StaticLog.setLog(new Log("administrator-fixture"));Fixture s=new Fixture(Files.createTempDirectory("admin-model-fixture-").resolve("admin-dashboard"));JSONObject catalog=AdministratorFeatures.catalog(s);check(catalog.getJSONArray("sections").length()==12,"All native model domains available");check(catalog.getJSONArray("permissions").length()>20,"Real native permission enum");check(catalog.getJSONArray("reports").length()>15,"Native report registry");check(!catalog.toString().contains("Fixture-secret-password"),"Catalog never includes passwords");
  for(String domain:AdministratorFeatures.TYPES.keySet()){JSONObject rows=AdministratorFeatures.rows(s,domain);check(rows.has("schema")&&rows.has("rows"),"Schema works: "+domain);}
  for(String section:List.of("autojudges","connections","notifications","scoring","deliveries","playback","eventfeeds","inputValidation","shadow","plugins")){check(AdministratorFeatures.query(s,new JSONObject().put("section",section))!=null,"Native query works: "+section);}
  for(String report:List.of("LanguagesReport","GroupsReport","JudgementReport")){JSONObject value=AdministratorFeatures.report(s,new JSONObject().put("report",report));check(value.getString("text").length()>0,"Native report generated: "+report);}
  JSONObject group=command("save").put("domain","groups").put("create",true).put("fields",new JSONObject().put("DisplayName","Division A").put("GroupId",1).put("DisplayOnScoreboard",true));AdministratorFeatures.operations(s,group);check(s.data.getGroups().length==1,"Native group added");
  JSONObject account=command("save").put("domain","accounts").put("create",true).put("type","TEAM").put("site",1).put("password","New-team-password-long").put("fields",new JSONObject().put("DisplayName","New Team")).put("groups",new JSONArray().put(s.data.getGroups()[0].getElementId().toString()));AdministratorFeatures.operations(s,account);Account team=Arrays.stream(s.data.getAccounts()).filter(a->a.getDisplayName().equals("New Team")).findFirst().orElseThrow();check(team.getGroupIds().size()==1,"Native account group membership");check(team.isAllowed(Permission.Type.LOGIN),"Native default permissions applied");
  JSONObject forbidden=command("save").put("domain","accounts").put("id",s.data.getAccount(new ClientId(1,ClientType.Type.ADMINISTRATOR,2)).getElementId().toString()).put("fields",new JSONObject()).put("permissions",new JSONArray());rejects(s,forbidden,"service permissions");
  rejects(s,command("save").put("domain","languages").put("id",s.data.getLanguages()[0].getElementId().toString()).put("fields",new JSONObject().put("CompileCommandLine","/bin/sh -c unsafe")),"unsafe active compiler");check(s.data.getLanguages()[0].getCompileCommandLine().startsWith("/opt/lcpc/bin/"),"Invalid edits do not mutate cached live model");
  AdministratorFeatures.operations(s,command("save").put("domain","languages").put("create",true).put("fields",new JSONObject().put("DisplayName","Prepared custom language").put("Active",false).put("CompileCommandLine","custom-compiler")));check(s.data.getLanguages().length==2,"Inactive custom language can be prepared");
  JSONObject scoring=AdministratorFeatures.scoring(s).getJSONObject("properties");AdministratorFeatures.operations(s,command("scoring.save").put("properties",scoring));check(!s.data.getContestInformation().getScoringProperties().isEmpty(),"Native scoring properties updated");
  Account judge=s.data.getAccount(new ClientId(1,ClientType.Type.JUDGE,1));AdministratorFeatures.operations(s,command("autojudge.save").put("id",judge.getElementId().toString()).put("enabled",true).put("filter",new JSONObject().put("problems",new JSONArray().put(s.data.getProblems()[0].getElementId().toString()))));check(s.data.getClientSettings(judge.getClientId()).getAutoJudgeFilter().isFilteringProblems(),"Native auto-judge problem filter");
  JSONObject notifications=command("notifications.save").put("id",s.data.getProblems()[0].getElementId().toString());for(String key:List.of("FinalNotificationYes","FinalNotificationNo","PreliminaryNotificationYes","PreliminaryNotificationNo"))notifications.put(key,new JSONObject().put("suppressed",key.startsWith("Preliminary")).put("cutoff",240));AdministratorFeatures.operations(s,notifications);check(AdministratorFeatures.notifications(s).getJSONArray("rows").length()==1,"Verdict notifications persisted");notifications.getJSONObject("PreliminaryNotificationYes").put("suppressed",false);rejects(s,notifications,"preliminary leakage");
  JSONObject bulk=AdministratorFeatures.operations(s,command("accounts.bulk").put("type","JUDGE").put("site",1).put("count",3).put("prefix","Judge"));check(bulk.getJSONArray("credentials").length()==3,"Bulk account credentials returned only on creation");check(bulk.getJSONArray("credentials").getJSONObject(0).getString("password").length()>=32,"Bulk uses random passwords");
  int before=s.data.getAccounts().length;JSONObject preview=AdministratorFeatures.operations(s,command("accounts.import").put("preview",true).put("rows",new JSONArray().put(new JSONObject().put("name","CSV Team").put("login","team99").put("type","TEAM").put("site",1))));check(preview.getInt("count")==1&&s.data.getAccounts().length==before,"CSV preview has no mutations");
  int count=s.calls.size();try{AdministratorFeatures.patch("accounts",new Account(new ClientId(1,ClientType.Type.TEAM,1),"",1),new JSONObject().put("Password","hidden"));throw new AssertionError("Reflection allowlist bypass");}catch(IllegalArgumentException expected){checks++;}check(s.calls.size()==count,"Unknown fields never reach native controller");
  JSONObject tests=AdministratorFeatures.tests(s,new JSONObject().put("id",s.data.getProblems()[0].getElementId().toString()));check(tests.getJSONArray("rows").getJSONObject(0).getInt("inputBytes")==3,"Private test metadata from real buffers");
  Files.writeString(s.privateBase.getParent().resolve("server.log"),"known secret Fixture-secret-password should be redacted");JSONObject tail=AdministratorFeatures.logs(s,new JSONObject().put("role","server"));check(tail.getString("text").contains("[REDACTED]")&&!tail.toString().contains("Fixture-secret-password"),"Service log redaction happens before export");
  int originalGroups=s.data.getGroups().length;JSONObject bundle=new JSONObject().put("format","PC2-DASHBOARD-CONFIG-1").put("domain","groups").put("records",new JSONArray().put(new JSONObject().put("fields",new JSONObject().put("DisplayName","Imported division").put("GroupId",8).put("DisplayOnScoreboard",true))));
  int sent=s.calls.size();JSONObject plan=AdministratorConfig.preview(s,new JSONObject().put("bundle",bundle));check(s.data.getGroups().length==originalGroups&&s.calls.size()==sent,"Configuration preview cannot write native state");AdministratorConfig.commit(s,new JSONObject().put("token",plan.getString("token")));check(s.data.getGroups().length==originalGroups+1,"Validated configuration batch commits");
  try{AdministratorConfig.commit(s,new JSONObject().put("token",plan.getString("token")));throw new AssertionError("Plan replay");}catch(IllegalArgumentException expected){checks++;}
  plan=AdministratorConfig.preview(s,new JSONObject().put("bundle",bundle));s.data.getContestInformation().setContestShortName("Concurrent change");try{AdministratorConfig.commit(s,new JSONObject().put("token",plan.getString("token")));throw new AssertionError("Stale plan");}catch(IllegalArgumentException expected){checks++;}
  bundle.getJSONArray("records").put(new JSONObject().put("fields",new JSONObject().put("DisplayName","Unsafe import").put("notAField","x")));int previous=s.calls.size();try{AdministratorConfig.preview(s,new JSONObject().put("bundle",bundle));throw new AssertionError("Invalid batch");}catch(IllegalArgumentException expected){checks++;}check(s.calls.size()==previous,"A later validation failure cannot partially import earlier rows");
  Path replayDir=s.privateBase.resolve("replays").resolve("a".repeat(32));Files.createDirectories(replayDir);Path source=replayDir.resolve("main.cpp");Files.writeString(source,"int main() {return 0;}\n");Path manifest=replayDir.resolve("dashboard-native.replay");Files.writeString(manifest,"action=RUN_SUBMIT|id=1|site=1|submitclient=team1|problem=Fixture problem|language=GNU C++17|mainfile="+source+"|elapsed=1000\n");
  int actions=s.calls.size();JSONObject dataset=AdministratorFeatures.operations(s,command("playback.import").put("directory",replayDir.toString()).put("main",manifest.getFileName().toString()).put("name","Isolated replay fixture"));check(dataset.getInt("events")==1&&s.calls.size()==actions,"Native replay import parses sources without writes or execution");
  AdministratorFeatures.operations(s,command("playback.start").put("id",dataset.getString("id")).put("intervalMs",100));check(s.lastPlayback!=null&&s.lastPlayback.isStarted()&&s.lastPlayback.getMinimumPlaybackRecords()==1,"Native server alone receives playback start with exact event count");check(s.data.getRuns().length==0&&s.calls.size()==actions+1,"Client adapter never executes a duplicate replay worker");
  check(AdministratorFeatures.query(s,new JSONObject().put("section","playback")).getJSONArray("rows").getJSONObject(0).getBoolean("started"),"Playback UI reads native acknowledgement state");AdministratorFeatures.operations(s,command("playback.stop").put("id",dataset.getString("id")));check(!s.lastPlayback.isStarted(),"Playback stop is forwarded to native server");
  Problem colored=AdministratorFeatures.copy(s.data.getProblems()[0]);BalloonSettings balloons=new BalloonSettings("Fixture balloons",1);balloons.setPrintBalloons(false);balloons.setEmailBalloons(false);balloons.addColor(colored,"Old blue","#0000ff");s.data.addBalloonSettings(balloons);
  ProblemColors.apply(colored,new JSONObject().put("colorName","Red").put("colorRGB","#ff0000"));ProblemColors.sync(s,colored);check(s.data.getBalloonSettings(1).getColor(colored).equals("Red")&&s.data.getBalloonSettings(1).getColorRGB(colored).equals("#ff0000"),"Problem color propagates to native balloon delivery settings");check(!s.data.getBalloonSettings(1).isPrintBalloons()&&!s.data.getBalloonSettings(1).isEmailBalloons(),"Color edit preserves printer and mail activation");
  s.data.updateProblem(colored);s.data.addSite(new Site("Second fixture site",2));AdministratorFeatures.operations(s,command("save").put("domain","balloons").put("create",true).put("site",2).put("fields",new JSONObject().put("LinesPerPage",50).put("PrintBalloons",false).put("EmailBalloons",false)));check(s.data.getBalloonSettings(2).getColor(colored).equals("Red"),"New balloon service inherits canonical problem colors");
  try{ProblemColors.apply(colored,new JSONObject().put("colorName","Unsafe").put("colorRGB","red;display:none"));throw new AssertionError("Invalid balloon color");}catch(IllegalArgumentException expected){checks++;}check(colored.getColorName().equals("Red"),"Invalid color cannot partially change the problem");
  s.data.getContestTime().startContestClock();rejects(s,group,"configuration while running");s.data.getContestTime().stopContestClock();
 }
}
